-- Permission vocabulary and system roles of the digest module
-- Generated by metaphor-schema
--
-- Writes into the identity module's tables (public.permissions, public.roles,
-- public.role_permissions), so those migrations must have run first. Inserts what is
-- missing and never deletes or revokes: what a tenant changed survives a re-run.

DO $$
BEGIN
    IF to_regclass('public.permissions') IS NULL
       OR to_regclass('public.roles') IS NULL
       OR to_regclass('public.role_permissions') IS NULL THEN
        RAISE NOTICE 'seed of the digest permissions skipped: the identity module has not created public.permissions, public.roles and public.role_permissions';
        RETURN;
    END IF;

    UPDATE public.permissions p SET description = v.description
      FROM (VALUES
            ('digest_digest:action_activate'::text, 'digest_digest'::text, 'action_activate'::text, 'Action activate digest digest'::text),
            ('digest_digest:action_deactivate'::text, 'digest_digest'::text, 'action_deactivate'::text, 'Action deactivate digest digest'::text),
            ('digest_digest:read'::text, 'digest_digest'::text, 'read'::text, 'Read digest digest'::text),
            ('digest_digest_kpi:create'::text, 'digest_digest_kpi'::text, 'create'::text, 'Create digest digest kpi'::text),
            ('digest_digest_kpi:delete'::text, 'digest_digest_kpi'::text, 'delete'::text, 'Delete digest digest kpi'::text),
            ('digest_digest_kpi:purge'::text, 'digest_digest_kpi'::text, 'purge'::text, 'Purge digest digest kpi'::text),
            ('digest_digest_kpi:read'::text, 'digest_digest_kpi'::text, 'read'::text, 'Read digest digest kpi'::text),
            ('digest_digest_kpi:restore'::text, 'digest_digest_kpi'::text, 'restore'::text, 'Restore digest digest kpi'::text),
            ('digest_digest_kpi:update'::text, 'digest_digest_kpi'::text, 'update'::text, 'Update digest digest kpi'::text),
            ('digest_subscription:read'::text, 'digest_subscription'::text, 'read'::text, 'Read digest subscription'::text),
            ('digest_subscription:resubscribe'::text, 'digest_subscription'::text, 'resubscribe'::text, 'Resubscribe digest subscription'::text),
            ('digest_subscription:unsubscribe'::text, 'digest_subscription'::text, 'unsubscribe'::text, 'Unsubscribe digest subscription'::text),
            ('digest_tip:create'::text, 'digest_tip'::text, 'create'::text, 'Create digest tip'::text),
            ('digest_tip:delete'::text, 'digest_tip'::text, 'delete'::text, 'Delete digest tip'::text),
            ('digest_tip:purge'::text, 'digest_tip'::text, 'purge'::text, 'Purge digest tip'::text),
            ('digest_tip:read'::text, 'digest_tip'::text, 'read'::text, 'Read digest tip'::text),
            ('digest_tip:restore'::text, 'digest_tip'::text, 'restore'::text, 'Restore digest tip'::text),
            ('digest_tip:update'::text, 'digest_tip'::text, 'update'::text, 'Update digest tip'::text),
            ('digest_tip_user:create'::text, 'digest_tip_user'::text, 'create'::text, 'Create digest tip user'::text),
            ('digest_tip_user:delete'::text, 'digest_tip_user'::text, 'delete'::text, 'Delete digest tip user'::text),
            ('digest_tip_user:purge'::text, 'digest_tip_user'::text, 'purge'::text, 'Purge digest tip user'::text),
            ('digest_tip_user:read'::text, 'digest_tip_user'::text, 'read'::text, 'Read digest tip user'::text),
            ('digest_tip_user:restore'::text, 'digest_tip_user'::text, 'restore'::text, 'Restore digest tip user'::text),
            ('digest_tip_user:update'::text, 'digest_tip_user'::text, 'update'::text, 'Update digest tip user'::text)
      ) AS v(name, resource, action, description)
     WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL
       AND p.description IS DISTINCT FROM v.description;

    INSERT INTO public.permissions (name, resource, action, description)
    SELECT v.name, v.resource, v.action, v.description
      FROM (VALUES
            ('digest_digest:action_activate'::text, 'digest_digest'::text, 'action_activate'::text, 'Action activate digest digest'::text),
            ('digest_digest:action_deactivate'::text, 'digest_digest'::text, 'action_deactivate'::text, 'Action deactivate digest digest'::text),
            ('digest_digest:read'::text, 'digest_digest'::text, 'read'::text, 'Read digest digest'::text),
            ('digest_digest_kpi:create'::text, 'digest_digest_kpi'::text, 'create'::text, 'Create digest digest kpi'::text),
            ('digest_digest_kpi:delete'::text, 'digest_digest_kpi'::text, 'delete'::text, 'Delete digest digest kpi'::text),
            ('digest_digest_kpi:purge'::text, 'digest_digest_kpi'::text, 'purge'::text, 'Purge digest digest kpi'::text),
            ('digest_digest_kpi:read'::text, 'digest_digest_kpi'::text, 'read'::text, 'Read digest digest kpi'::text),
            ('digest_digest_kpi:restore'::text, 'digest_digest_kpi'::text, 'restore'::text, 'Restore digest digest kpi'::text),
            ('digest_digest_kpi:update'::text, 'digest_digest_kpi'::text, 'update'::text, 'Update digest digest kpi'::text),
            ('digest_subscription:read'::text, 'digest_subscription'::text, 'read'::text, 'Read digest subscription'::text),
            ('digest_subscription:resubscribe'::text, 'digest_subscription'::text, 'resubscribe'::text, 'Resubscribe digest subscription'::text),
            ('digest_subscription:unsubscribe'::text, 'digest_subscription'::text, 'unsubscribe'::text, 'Unsubscribe digest subscription'::text),
            ('digest_tip:create'::text, 'digest_tip'::text, 'create'::text, 'Create digest tip'::text),
            ('digest_tip:delete'::text, 'digest_tip'::text, 'delete'::text, 'Delete digest tip'::text),
            ('digest_tip:purge'::text, 'digest_tip'::text, 'purge'::text, 'Purge digest tip'::text),
            ('digest_tip:read'::text, 'digest_tip'::text, 'read'::text, 'Read digest tip'::text),
            ('digest_tip:restore'::text, 'digest_tip'::text, 'restore'::text, 'Restore digest tip'::text),
            ('digest_tip:update'::text, 'digest_tip'::text, 'update'::text, 'Update digest tip'::text),
            ('digest_tip_user:create'::text, 'digest_tip_user'::text, 'create'::text, 'Create digest tip user'::text),
            ('digest_tip_user:delete'::text, 'digest_tip_user'::text, 'delete'::text, 'Delete digest tip user'::text),
            ('digest_tip_user:purge'::text, 'digest_tip_user'::text, 'purge'::text, 'Purge digest tip user'::text),
            ('digest_tip_user:read'::text, 'digest_tip_user'::text, 'read'::text, 'Read digest tip user'::text),
            ('digest_tip_user:restore'::text, 'digest_tip_user'::text, 'restore'::text, 'Restore digest tip user'::text),
            ('digest_tip_user:update'::text, 'digest_tip_user'::text, 'update'::text, 'Update digest tip user'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

END $$;
